class Element {
  constructor(props) {
    this.id = props.id || 0;
    this.isDisplay = props.isDisplay ?? true;
    this.x = props.x || 0;
    this.y = props.y || 0;
    this.w = props.w || 0;
    this.h = props.h || 0;
    this.localX = props.localX || 0;
    this.localY = props.localY || 0;
    this.scaleX = props.scaleX || 1.0;
    this.scaleY = props.scaleY || 1.0;

    this.fillColor = props.fillColor || color('rgba(0, 0, 0, 100)');
    this.strokeColor = props.strokeColor || color('rgba(0, 0, 0, 0)');
    this.backgroundColor = props.backgroundColor || color('rgba(0, 0, 0, 0)');
    this.offsetColorStop = props.offsetColorStop || 0;
    this.offsetColorStopAccel = this.offsetColorStopAccel || random(-0.0075, 0.0075);
    this.gradationStopNoise = random(2.0);
    this.gradientX = props.gradientX || 0;
    this.gradientY = props.gradientY || 0;
    this.gradientStartAngle = random(TWO_PI);
    this.colors = props.colors || palette.colors;
    this.angle = props.angle || 0;
    this.centerX = 0;
    this.centerY = 0;
    noStroke();
    this.anime();
  }

  anime = () => {
    gsap.to(this, {
      angle: this.angle + getRandomAngleInRadians(8, -TWO_PI, TWO_PI),
      duration: 1.0,
      delay: 2.0,
      ease: "expo.inOut",
      onComplete: () => {
        this.anime();
      },
    });
  }

  run = () => {
    if (!this.isDisplay) return
    push();
    translate(this.x, this.y);
    scale(this.scaleX, this.scaleY);
    rotate(this.angle);
    setFillConicGradient(0, this.centerX, this.centerY, this.colors, null, this.offsetColorStop, 'liner');
    rect(this.centerX, this.centerY, this.w, this.h);
    pop();
  }
}

////////////////////////////////////////////////

class Motif {
  constructor(props) {
    this.isDisplay = props.isDisplay ?? true;
    this.id = props.id || 0;
    this.x = props.x || 0;
    this.y = props.y || 0;
    this.w = props.w || 100;
    this.h = props.h || 100;
    this.angle = props.angle || 0;
    this.elements = props.elements || []; 
    this.elementW = this.w;
    this.elementH = this.h;
    this.repeat = 6;

    const size = 1000;
    for (let i = 0; i < this.repeat; i++) {
      const currentSize = i * (size / this.repeat);
      const element = new Element({
        id: i,
        x: 0,
        y: 0,
        angle : getRandomAngleInRadians(8, -TWO_PI, TWO_PI),
        w: currentSize,
        h: currentSize,
        colors: generateColorScheme(palette.colors[randomInt(0, palette.colors.length - 1)], 'monochromatic'),
      })
      this.elements.push(element);
    }
  }

  run = () => {
    push();
    translate(this.x, this.y);
    rotate(this.angle);
    blendMode(BURN);
    for (let i = 0; i < this.elements.length; i++) {
      var element = this.elements[i];
      element.run();
    }
    pop();
  }
}


////////////////////////////////////////////////

class Module {
  constructor(props) {
    this.isDisplay = props.isDisplay ?? true;
    this.id = props.id || 0;
    this.x = props.x || 0;
    this.y = props.y || 0;
    this.w = props.w || 1000;
    this.h = props.h || 1000;
    this.angle = props.angle || 0;
    this.motifs = [];

    this.repeatX = 2;
    this.repeatY = 2;
    this.motifW = this.w / this.repeatX + 0;
    this.motifH = this.h / this.repeatY + 0;
    this.offsetX = - (this.repeatX * this.motifW) / 2 + this.motifW / 2;
    this.offsetY = - (this.repeatY * this.motifH) / 2 + this.motifH / 2;

    for (let i = 0; i < this.repeatX; i++) {
      for (let j = 0; j < this.repeatY; j++) {
        const motif = new Motif({
          x: i * this.motifW + this.offsetX,
          y: j * this.motifH + this.offsetY,
          w: this.w,
          h: this.h,
        })
        this.motifs.push(motif)
      }
    }
  }

  run = () => {
    if (!this.isDisplay) return;
    push();
    translate(this.x, this.y);
    rotate(this.angle);
    for (let i = 0; i < this.motifs.length; i++) {
      var motif = this.motifs[i];
      motif.run();
    }
    pop();
  }
}

