function drawGuide(x, y, w, h, strokeWidth = 0.5, fillColor = color('rgba(255, 0, 0, 0.1)'), strokeColor = color('rgba(255, 0, 0, 0.2)'), centerColor = color('rgba(255, 0, 0, 1)')) {
  strokeWeight(strokeWidth);
  fill(fillColor);
  stroke(strokeColor);
  rect(x, y, w, h);
  fill(centerColor);
  circle(0, 0, 5);
}

function drawRect(x, y, w, h, strokeWidth = 0) {
  rect(x, y, w - strokeWidth, h - strokeWidth);
}

function drawSquare(x, y, w, strokeWidth = 0) {
  square(x, y, w - strokeWidth);
}

function drawEllipse(x, y, w, h, strokeWidth = 0) {
  ellipse(x, y, w - strokeWidth, h - strokeWidth);
}

function drawCircle(x, y, w, strokeWidth = 0) {
  circle(x, y, w - strokeWidth);
}

function drawArc(x, y, w, h, start, stop, mode = 'CHORD', detail = 25, strokeWidth = 0) {
  arc(x, y, w - strokeWidth, h - strokeWidth, start, stop, mode, detail)
}

function drawEquilateralTriangle(centerX, centerY, radius) {
  beginShape();
  for (let i = 0; i < 3; i++) {
    const angle = TWO_PI * i / 3 - HALF_PI;
    vertex(centerX + radius * cos(angle), centerY + radius * sin(angle));
  }
  endShape(CLOSE); 
}

function drawTriangle(x1, y1, x2, y2, x3, y3) {
  beginShape();
  vertex(x1, y1);
  vertex(x2, y2);
  vertex(x3, y3);
  endShape(CLOSE); 
}

function drawQuadrilateral(x1, y1, x2, y2, x3, y3, x4, y4) {
  beginShape();
  vertex(x1, y1);
  vertex(x2, y2);
  vertex(x3, y3);
  vertex(x4, y4);
  endShape(CLOSE); 
}

function drawRhombus(centerX, centerY, radius1, radius2) {
  beginShape();
  for (let i = 0; i < 4; i++) {
    const radius = (i % 2 == 0) ? radius2 : radius1;
    vertex(centerX + radius * cos(HALF_PI * i), centerY + radius * sin(HALF_PI * i));
  }
  endShape(CLOSE);
}

function drawPolygon(centerX, centerY, radius, numPoints) {
  if (numPoints < 3) {
    throw new Error('numVertices must be 3 or greater');
  }
  beginShape();
  for (let i = 0; i < numPoints; i++) {
    vertex(centerX + radius * cos(TWO_PI * i / numPoints), centerY + radius * sin(TWO_PI * i / numPoints));
  }
  endShape(CLOSE);
}

function drawStar(centerX, centerY, outerRadius, innerRadius, numPoints) {
  if (
    outerRadius <= 0 ||
    innerRadius <= 0 ||
    innerRadius >= outerRadius ||
    numPoints < 3 ||
    !Number.isInteger(numPoints)
  ) {
    console.error('Invalid arguments for drawStar');
    return;
  }
  const angleStep = TWO_PI / numPoints;
  const halfAngleStep = angleStep / 2.0;
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += angleStep) {
    const outerX = centerX + cos(angle - HALF_PI) * outerRadius;
    const outerY = centerY + sin(angle - HALF_PI) * outerRadius;
    vertex(outerX, outerY);
    const innerX = centerX + cos(angle - HALF_PI + halfAngleStep) * innerRadius;
    const innerY = centerY + sin(angle - HALF_PI + halfAngleStep) * innerRadius;
    vertex(innerX, innerY);
  }
  endShape(CLOSE);
}

function drawAstroid(centerX, centerY, radius, numPoints) {
  if (radius <= 0 || numPoints < 3 || !Number.isInteger(numPoints)) {
    console.error('Invalid arguments for drawAstroid');
    return;
  }
  const vertexNum = numPoints - 1;
  var angleStep = TWO_PI / 360;
  beginShape();
  for (let theta = 0; theta < TWO_PI; theta += angleStep) {
    const x = radius * (vertexNum * cos(theta) + cos(-vertexNum * theta));
    const y = radius * (vertexNum * sin(theta) + sin(-vertexNum * theta));
    vertex(centerX + x, centerY + y);
  }
  endShape(CLOSE);
}

function drawInscribedSquare(centerX, centerY, w, h) {
  if (w <= 0 || h <= 0) {
    console.error('Invalid width or height for drawInscribedSquare');
    return;
  }
  const halfWidth = w / 2;
  const halfHeight = h / 2;
  beginShape();
  vertex(centerX, centerY - halfHeight);
  quadraticVertex(centerX + halfWidth, centerY - halfHeight, centerX + halfWidth, centerY);
  quadraticVertex(centerX + halfWidth, centerY + halfHeight, centerX, centerY + halfHeight);
  quadraticVertex(centerX - halfWidth, centerY + halfHeight, centerX - halfWidth, centerY);
  quadraticVertex(centerX - halfWidth, centerY - halfHeight, centerX, centerY - halfHeight);
  endShape(CLOSE);
}

function drawHarfPill(x, y, w, h, numSteps = 50) {
  if (w <= 0 || h <= 0) {
    console.error('drawHalfPill: Invalid width or height');
    return;
  }
  beginShape();
  vertex(x - w / 2, y - h / 2);
  vertex(x + w / 2, y - h / 2);
  vertex(x + w / 2, y + h / 4 - h / 4);
  vertex(x - w / 2, y + h / 4 - h / 4);
  vertex(x - w / 2, y - h / 4);
  for (let i = 0; i < numSteps; i++) {
    var angle = i * PI / numSteps;
    const vx = (w / 2) * cos(angle);
    const vy = (h / 2) * sin(angle);
    vertex(vx, vy);
  }
  endShape(CLOSE);
}

function drawSemicircleBack2(x, y, w, h) {
  arc(0, -h / 2, w, h, 0, PI);
  arc(0, h / 2, w, h, PI, 2 * PI);
}

function drawCirclesAscending(x, y, repeat, stepR, arcAngle) {
  for (let i = 0; i <= repeat; i++) {
    arc(x, y, i * stepR, i * stepR, 0, arcAngle);
  }
}

function drawCirclesDescending(x, y, repeat, stepR, arcAngle) {
  for (let i = repeat; i >= 0; i--) {
    arc(x, y, i * stepR, i * stepR, 0, arcAngle);
  }
}

function drawRectsAscending(x, y, repeat, stepR, arcAngle) {
  for (let i = 0; i <= repeat; i++) {
    rect(x, y, i * stepR, i * stepR, 0, arcAngle);
  }
}

function drawRectsDescending(x, y, repeat, stepR, arcAngle) {
  for (let i = repeat; i >= 0; i--) {
    rect(x, y, i * stepR, i * stepR, 0, arcAngle);
  }
}

function drawPetal(x, y, w, h, angle, topWidthFactor, bottomWidthFactor) {
  push();
  translate(x, y);
  rotate(angle);
  beginShape();
  vertex(0, -h / 2);
  bezierVertex(w * topWidthFactor / 2, -h / 2, w * topWidthFactor / 2, h / 4, 0, h / 2);
  bezierVertex(-w * bottomWidthFactor / 2, h / 4, -w * bottomWidthFactor / 2, -h / 2, 0, -h / 2);
  endShape(CLOSE);
  pop();
}

function drawCapsule(x, y, w, h) {
  const r = h / 2;
  rect(x, y, w, h);
  arc(x - w / 2 + 0.5, y, h, h, HALF_PI, PI + HALF_PI);
  arc(x + w / 2 - 0.5, y, h, h, -HALF_PI, HALF_PI);
}


